static void graph_pedal(void){char b[32];static const char *const result[]={"NO MATCH","TRIGGER","DUP SUPPRESSED","LEARN CAPTURED","PATCH DISABLED","QUEUE FULL"};
 cv_text(4,0,&FONT_S,sm_usb_host?"USB ROLE: PEDAL":"USB ROLE: COMPUTER",C_HI);
 str_cpy(b,sm_usb_device_seen?"PEDAL DEV YES":"PEDAL DEV NO",32);sm_text_add(b,sm_usb_midi_seen?"  MIDI YES":"  MIDI NO");cv_text(4,18,&FONT_S,b,C_GRAY);
 if(sm_last[0])sm_message_text(b,0);else str_cpy(b,"NO MIDI RECEIVED",32);cv_text(4,36,&FONT_S,b,C_WHITE);
 str_cpy(b,sm_last_match<SM_ACTIONS?SM_ACTION_NAME[sm_last_match]:"UNASSIGNED",32);sm_text_add(b," ");sm_text_add(b,result[sm_last_result<6?sm_last_result:0]);cv_text(4,54,&FONT_S,b,C_GRAY);
 if(sm_learn_state==2){sm_message_text(b,1);cv_text(4,72,&FONT_S,b,C_HI);cv_text(4,90,&FONT_S,"ACCEPT? KNOB 3 / CANCEL K2",C_WHITE);}
 else if(sm_learn_state==1){cv_text(4,72,&FONT_S,"PRESS ONE PEDAL SWITCH",C_HI);cv_text(4,90,&FONT_S,"CC / PC; KNOB 2 CANCELS",C_GRAY);}
 else {cv_text(4,72,&FONT_S,SM_ACTION_NAME[xv[X_PEDACT]%SM_ACTIONS],C_HI);cv_text(4,90,&FONT_S,(uint32_t)(fm1_ms-sm_trigger_at)<1000u && sm_trigger_count?"TEST: ACTION TRIGGERED":"LEARN: KNOB 2",C_GRAY);}
 cv_text(4,108,&FONT_S,"COMPUTER: EDITOR/AUDIO/UPDATE",C_GRAY);
}
static void graph_scenes(void){uint32_t i;char b[32];for(i=0;i<4;i++){str_cpy(b,i==xv[X_SCENE]-1u?"> SCENE ":"  SCENE ",32);sm_text_num(b,i+1);sm_text_add(b,sm_scenes[i].valid?" STORED":" EMPTY");cv_text(4,i*22,&FONT_S,b,i==sm_scene_index?C_HI:C_GRAY);}cv_text(4,100,&FONT_S,"SAVE PROGRAM TO KEEP SCENES",C_WHITE);}
static void graph_setlist(void){char b[32];uint32_t pos=(uint32_t)(xv[X_LISTPOS]-1u)%32u,slot=sm_setlist[pos];str_cpy(b,"ENTRY ",32);sm_text_num(b,pos+1);sm_text_add(b," / ");sm_text_num(b,sm_setlist_len);cv_text(4,4,&FONT_S,b,C_HI);cv_text(4,28,&FONT_S,program_names[slot],C_WHITE);cv_text(4,50,&FONT_S,project_used(slot)?"SAVED PROGRAM":"EMPTY PROGRAM REFERENCE",C_GRAY);str_cpy(b,"PEDAL POSITION ",32);if(sm_setlist_active)sm_text_num(b,sm_setlist_pos+1u);else sm_text_add(b,"NOT STARTED");cv_text(4,74,&FONT_S,b,C_GRAY);cv_text(4,100,&FONT_S,sm_pending_program==255?"GO: LOAD THIS ENTRY":"WAITING FOR QUIET LOAD",C_WHITE);}
static void graph_filter_caps(void){const sm_filter_cap_t *c=&SM_FILTER_CAP[TSEL->eng_req%NENGINES];char b[32];cv_text(4,0,&FONT_S,TSEL->eng_req==ENGI_HYBRID?"HYBRID: FILTER 1 BASE":c->model>=0?"SELECTABLE NATIVE FILTER":c->fixed,C_HI);cv_text(4,22,&FONT_S,"-- = CONTROL NOT AVAILABLE",C_GRAY);cv_text(4,44,&FONT_S,TSEL->eng_req==ENGI_HYBRID?"FILTER 2 / ROUTE: EDITOR":"NATIVE UNITS AND RANGES",C_GRAY);cv_text(4,66,&FONT_S,"COMP = ESTIMATED ATTENUATION",C_GRAY);fmt_fix(b,-5*sm_filter_comp_steps(TSEL),1);cv_text(4,88,&FONT_S,b,C_WHITE);cv_text(64,88,&FONT_S,"dB; OFF BY DEFAULT",C_GRAY);}
